{"function": "Suggest transport", "situation": "Planning how to get somewhere", "cue": "Suggest taking the bus to go somewhere.", "text": "ไปรถเมล์กันไหม ครับ", "english": "Shall we go by bus?", "speaker": "male"},
{"function": "Ask about bus", "situation": "Wondering if the bus is available", "cue": "Ask if the bus is coming soon.", "text": "รถเมล์ มาหรือยัง ครับ", "english": "Has the bus come yet?", "speaker": "male"},
{"function": "Describe bus", "situation": "Talking about the bus size", "cue": "Say the bus is small.", "text": "รถเมล์ คันนั้น นิดหน่อย ครับ", "english": "That bus is a little bit small.", "speaker": "male"},
{"function": "Ask direction", "situation": "Asking for bus route", "cue": "Ask which bus goes to the city center.", "text": "รถเมล์ ไป ตัวเมือง คันไหน ครับ", "english": "Which bus goes to the city center?", "speaker": "male"},
{"function": "Agree to bus", "situation": "Confirming bus as transport", "cue": "Agree to take the bus.", "text": "ไป รถเมล์ ดี ครับ", "english": "Going by bus is good.", "speaker": "male"},
{"function": "Comment on bus", "situation": "Observing the bus", "cue": "Say the bus is crowded.", "text": "รถเมล์ คน เยอะ จัง ครับ", "english": "The bus is very crowded.", "speaker": "male"}
]}

